window.kbPageData["views/entry/k-f9f9ac95a0ab3307"] = {"key":"entry/k-f9f9ac95a0ab3307","state":{"route":"entry/k-f9f9ac95a0ab3307"},"node":{"id":"k-f9f9ac95a0ab3307","mode":"k","title":"联系的客观性与新联系的建立","type":"原理与机制","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["联系的客观性与依据固有联系建立新联系"],"qs":["政治理论必刷100题#9"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"主类":["原理与机制"],"出处性质":["专项题干"],"学科":["政治理论"],"资料类别":["政治理论专项"]},"directorySummary":"事物的联系具有客观性，不以人的意志为转移。人可以依据事物固有的联系，通过实践改变事物的状态或条件，建立新的联系。","review":{"definition":"事物的联系具有客观性，不以人的意志为转移。人可以依据事物固有的联系，通过实践改变事物的状态或条件，建立新的联系。","explanation":"当地以已有的温泉资源为基础，通过开发休闲度假区，把生态资源同旅游、养生和康体产业结合起来，进而增加农民收入。这一过程体现了B项所说的建立新联系。新联系由实践形成，仍具有客观性，因此C项把人为事物的联系说成具有主观性是错误的。","references":[],"evidence":"可以根据事物固有的联系，改变事物的状态，建立新的联系","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"政治理论必刷100题#9":{"paper":"政治理论必刷100题","n":9,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",3],"asrc":["国省考政治理论必刷100题.pdf",35],"card":"f53a602bfaff93b42ee1fbe7","links":[{"id":"k-f9f9ac95a0ab3307","role":"直接考查","why":"温泉开发以既有资源条件为基础，通过实践形成新的产业联系，人为事物的联系仍具客观性。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-f9f9ac95a0ab3307":[["政治理论必刷100题#9"]]}};
